   var row=GameObject.Find("Canvas").transform.Find("StackColumn/Viewport/Content/StackEntry_0");var mini=row.GetComponentsInChildren<UnityEngine.UI.Text>().First(t=>t.name=="Fallback");var source=row.Find("CompactEffect/Content/CompactNote").GetComponent<UnityEngine.UI.Text>();Check(mini.text.Length<80&&mini.preferredHeight<=mini.rectTransform.rect.height,lang+"/"+legacy+" thumbnail is bounded caption");Check(source.text.Contains("LEGACY_END_89"),lang+"/"+legacy+" complete fallback body survives thumbnail caption change");var toggle=row.Find("EffectToggle").GetComponent<UnityEngine.UI.Button>();Check(Click(toggle),lang+"/"+legacy+" expand reachable");yield return new WaitForSecondsRealtime(.15f);Check(row.Find("CompactEffect").GetComponent<UnityEngine.UI.ScrollRect>().enabled,lang+"/"+legacy+" stable expanded identity");
  }
 }
 GamePreferences.SetLanguage(language);GamePreferences.SetScale(scale);yield return null;while(!GamePreferences.Ready)yield return null;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(Sample(),1,false,null,null,"副本 · 只读布局预览");Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int i=0;i<10000;i++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});GamePreferences.SetLanguage(language);GamePreferences.SetScale(scale);Save("ERROR");yield break;}if(!next)break;yield return value;}}
